.share a:hover,.share button:hover{border-color:var(--sepia);color:var(--ink)}
.share svg{color:var(--sepia)}
/* tooltip terms */
dfn{font-style:normal;border-bottom:1px dashed var(--sepia);cursor:help}
/* print / PDF */
@media print{
